```python
class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def inorder(node):
    if node:
        inorder(node.left)
        print(node.data, end=" ")
        inorder(node.right)

def preorder(node):
    if node:
        print(node.data, end=" ")
        preorder(node.left)
        preorder(node.right)

def postorder(node):
    if node:
        postorder(node.left)
        postorder(node.right)
        print(node.data, end=" ")

def traverse_tree():
    # Create the binary tree
    root = Node(1)
    root.left = Node(2)
    root.right = Node(3)
    root.left.left = Node(4)
    root.left.right = Node(5)

    print("The binary tree is traversed successfully:")

    traversal_type = input("Enter the traversal type (inorder, preorder, or postorder): ").lower()

    if traversal_type == "inorder":
        inorder(root)
    elif traversal_type == "preorder":
        preorder(root)
    elif traversal_type == "postorder":
        postorder(root)
    else:
        print("Invalid traversal type. Please try again.")

# Call the function to start the program
traverse_tree()
```

This program creates a binary tree with nodes 1, 2, 3, 4, and 5, and then prompts the user to choose a traversal type. The program then calls the appropriate traversal function and prints the result.
